cat >> notbydefault/ui/static/app.css <<'EOF'

/* --- activity feed ------------------------------------------------------------------ */
.feed { list-style: none; margin: 0; padding: 0; position: relative; }
.feed::before { content: ""; position: absolute; left: 11px; top: 6px; bottom: 6px; border-left: 1px dashed var(--rule); }
.feed li { position: relative; padding: 0 0 16px 34px; min-width: 0; }
.feed li .dot { position: absolute; left: 4px; top: 4px; width: 15px; height: 15px; border-radius: 50%; background: var(--sheet); border: 2px solid var(--neutral); }
.feed li.k-caught .dot { border-color: var(--ink); }
.feed li.k-hook .dot { border-color: var(--bad); background: var(--bad-bg); }
.feed li.k-pivot .dot { border-color: var(--pivot); background: var(--pivot-bg); }
.feed li.k-requirement .dot { border-color: var(--warn); background: var(--warn-bg); }
.feed li.k-fit_check .dot { border-color: var(--ok); background: var(--ok-bg); }
.feed li.k-resolve .dot { border-color: var(--accent); }
.feed li.k-ui .dot { border-style: dashed; }
.feed .meta { display: flex; gap: 8px; align-items: center; flex-wrap: wrap; font: .72rem/1.4 var(--mono); color: var(--muted); text-transform: uppercase; letter-spacing: .05em; }
.feed .title { font-weight: 600; margin: 2px 0 1px; overflow-wrap: anywhere; }
.feed .title a { color: var(--ink); text-decoration: none; }
.feed .title a:hover { text-decoration: underline; }
.feed .detail { color: var(--ink-2); font-size: .88rem; overflow-wrap: anywhere; }
.effects { display: flex; flex-wrap: wrap; gap: 6px; margin-top: 6px; align-items: center; }
.effects .arrow { font-family: var(--mono); color: var(--muted); }
.effect { display: inline-flex; gap: 6px; align-items: center; font: .78rem/1 var(--mono); text-decoration: none; color: var(--ink); padding: 3px 6px 3px 3px; border: 1px solid var(--rule); border-radius: 999px; background: var(--sheet); }
.effect .pill { padding: 2px 6px; font-size: .64rem; }
.feed li.fresh { animation: fresh 2.4s ease-out; }
.feed li.fresh .dot { animation: ping 1.2s ease-out 2; }
@keyframes fresh { from { background: color-mix(in srgb, var(--warn-bg) 90%, transparent); } to { background: transparent; } }
@keyframes ping { 0% { box-shadow: 0 0 0 0 var(--warn); } 100% { box-shadow: 0 0 0 10px transparent; } }
.empty { border: 1px dashed var(--rule); border-radius: 8px; padding: 22px; text-align: center; color: var(--muted); background: color-mix(in srgb, var(--sheet) 60%, transparent); }
.empty b { display: block; color: var(--ink-2); font-family: var(--serif); font-size: 1.05rem; margin-bottom: 4px; }

/* --- tables --------------------------------------------------------------------- */
.table-wrap { overflow-x: auto; max-width: 100%; border: 1px solid var(--rule); border-radius: 8px; background: var(--sheet); }
table { border-collapse: collapse; width: 100%; font-size: .88rem; }
th, td { text-align: left; padding: 8px 10px; border-bottom: 1px solid var(--rule-2); vertical-align: top; }
th { font: 600 .68rem/1.3 var(--mono); text-transform: uppercase; letter-spacing: .07em; color: var(--muted); background: var(--paper-2); white-space: nowrap; }
tbody tr:last-child td { border-bottom: 0; }
td.num, th.num { text-align: right; font-family: var(--mono); white-space: nowrap; }
table.fit td { font-family: var(--mono); font-size: .8rem; white-space: nowrap; }
table.fit td:first-child { white-space: normal; min-width: 180px; font-weight: 600; }
table.fit tr.rec td { background: color-mix(in srgb, var(--ok-bg) 70%, transparent); }
table.fit tr.cur td:first-child { box-shadow: inset 3px 0 0 var(--ink); }
table.fit td.no { color: var(--bad); font-weight: 700; }
table.fit td.yes { color: var(--ok); font-weight: 700; }
table.md td, table.md th { white-space: normal; }

/* --- prose (rendered markdown) ------------------------------------------------------- */
.prose { overflow-wrap: anywhere; }
.prose h2, .prose h3, .prose h4 { margin: 1.2em 0 .4em; }
.prose ul, .prose ol { padding-left: 1.2em; }
.prose .table-wrap { margin: .6em 0 1em; }
pre.code, pre.block { background: var(--paper-2); border: 1px solid var(--rule-2); border-radius: 8px; padding: 12px 14px; overflow-x: auto; font-size: .8rem; line-height: 1.5; white-space: pre; }
pre.wrap { white-space: pre-wrap; overflow-wrap: anywhere; }
.diff .add { color: var(--ok); background: color-mix(in srgb, var(--ok-bg) 60%, transparent); display: inline-block; width: 100%; }
.diff .del { color: var(--bad); background: color-mix(in srgb, var(--bad-bg) 60%, transparent); display: inline-block; width: 100%; }
.diff .hunk { color: var(--pivot); }
.copy { cursor: pointer; }
.copy.done::after { content: " ✓"; color: var(--ok); }
.trace { display: inline-flex; align-items: center; gap: 6px; flex-wrap: wrap; }
.trace code { font-size: .78rem; }
footer.colophon { border-top: 1px solid var(--rule); color: var(--muted); font-size: .8rem; padding: 18px 0 30px; }
footer.colophon .wrap { display: flex; justify-content: space-between; gap: 12px; flex-wrap: wrap; }
EOF
cat > notbydefault/ui/static/theme.js <<'EOF'
// Runs before first paint: apply the remembered theme (if any) so there is no flash.
(function () {
  var t = null;
  try { t = window.localStorage.getItem("nbd-theme"); } catch (e) { t = null; }
  if (t === "light" || t === "dark") document.documentElement.setAttribute("data-theme", t);
})();
EOF

