  window.nbdCy = cy;
  document.addEventListener("nbd:theme", function () { cy.style(style()); });

  function layout(animate) {
    var eles = cy.elements().not(".filtered").not(".hidden");
    eles.layout({ name: window.cytoscapeDagre ? "dagre" : "breadthfirst", rankDir: "LR",
      nodeSep: 22, rankSep: 90, edgeSep: 10, animate: !!animate, animationDuration: 450,
      fit: true, padding: 24 }).run();
  }

