.type-filters { display: flex; flex-wrap: wrap; gap: 6px 10px; align-items: center; margin-bottom: 12px; }
.tf { display: inline-flex; align-items: center; gap: 6px; font: .8rem var(--mono); padding: 4px 8px; border: 1px solid var(--rule); border-radius: 6px; background: var(--sheet); cursor: pointer; }
.tf i { width: 14px; height: 10px; border: 1.5px solid var(--rule); background: var(--sheet); display: inline-block; }
.tf-goal i { background: var(--ink); border-color: var(--ink); border-radius: 3px; }
