.tf-alternative i { border-style: dashed; border-color: var(--muted); }
.tf-code i { background: var(--paper-2); }
.tf-pivot i { border-color: var(--pivot); background: var(--pivot-bg); }
.legend { display: inline-flex; gap: 6px; align-items: center; flex-wrap: wrap; margin-left: auto; }
