#cy { width: 100%; height: min(72vh, 680px); min-height: 420px; }
.graph-empty { position: absolute; inset: 40px; display: grid; place-content: center; }
.panel { position: sticky; top: 74px; max-height: calc(100vh - 90px); overflow: auto; }
.panel-title { font-family: var(--mono); font-size: 1.05rem; overflow-wrap: anywhere; }
.edge-key { margin-top: 12px; }
.toast { position: absolute; left: 16px; bottom: 16px; max-width: calc(100% - 32px); background: var(--ink); color: var(--paper); padding: 10px 14px; border-radius: 8px; font: 600 .85rem var(--sans); transform: translateY(20px); opacity: 0; transition: all .3s; pointer-events: none; }
.toast.show { transform: none; opacity: 1; }

