{% extends "base.html" %}
{% from "_macros.html" import trace %}
{% block title %}Evals{% endblock %}
{% macro fmt(v, rate) -%}
{%- if v is none -%}<span class="muted">-</span>{%- elif rate -%}{{ "%.0f%%"|format(v * 100) }}{%- elif v is float -%}{{ "%.2f"|format(v) }}{%- else -%}{{ v }}{%- endif -%}
{%- endmacro %}
{% block content %}
<div class="page-head">
  <div>
    <div class="eyebrow">eval/results · measuring NotByDefault itself</div>
    <h1>Evals, version by version</h1>
    <p>Original cases are comparable across versions; held-out cases were written after the fixes and are shown separately.</p>
  </div>
</div>
{% if ev.columns %}
<div class="grid-3 eval-bars">
  {% for s in ev.sections %}
  <figure class="sheet bars">
    <figcaption><b>{{ s.name }}</b> <span class="small muted">cases passed</span></figcaption>
    <svg viewBox="0 0 300 {{ 22 * ev.columns|length + 6 }}" width="100%" role="img" aria-label="{{ s.name }}: share of cases passed per version">
      {% for c in ev.columns %}{% set y = 4 + loop.index0 * 22 %}{% set r = s.passed[loop.index0] %}
      <text x="0" y="{{ y + 13 }}" class="bar-label">{{ c.name }}</text>
      <rect x="92" y="{{ y + 2 }}" width="170" height="14" rx="3" class="bar-track"/>
      {% if r is not none %}<rect x="92" y="{{ y + 2 }}" width="{{ (170 * r)|round(1) }}" height="14" rx="3" class="bar {{ 'held' if c.heldout }}"/>
      <text x="268" y="{{ y + 13 }}" class="bar-value">{{ "%.0f%%"|format(r * 100) }}</text>{% else %}<text x="268" y="{{ y + 13 }}" class="bar-value muted-fill">–</text>{% endif %}
      {% endfor %}
    </svg>
  </figure>
  {% endfor %}
</div>

{% for s in ev.sections %}
<div class="section-title"><h2>{{ s.name }}</h2><span class="src">eval/cases/{{ s.name }}.json · eval/cases/heldout/</span></div>
