@media (max-width: 560px) { .eval-bars { grid-template-columns: 1fr; } }
figure.bars { margin: 0; padding: 14px 16px; }
figure.bars figcaption { margin-bottom: 8px; font-family: var(--mono); }
.bar-label, .bar-value { font: 11px var(--mono); fill: var(--ink-2); }
.bar-value { text-anchor: start; font-weight: 700; fill: var(--ink); }
.muted-fill { fill: var(--muted); }
.bar-track { fill: var(--paper-2); }
.bar { fill: var(--ok); }
.bar.held { fill: var(--accent); }
table.evals td:first-child { white-space: nowrap; }
th.held, td.held { background: color-mix(in srgb, var(--accent) 7%, transparent); }
.costs h2 { font-size: 1.15rem; margin-top: 1.4em; }
.costs h2:first-child { margin-top: 0; }

